{"summary":"Added a small, playable puzzle: rotate nine tiles to connect the light.","operations":[{"op":"create","object":{"id":"puzzle_heading","kind":"text","title":"A little something to play with","text":"An optional, one-minute puzzle: connect the light.","x":24,"y":16,"width":620,"height":70,"color":"ink"}},{"op":"create","object":{"id":"puzzle_help","kind":"text","title":"Your move","text":"Turn tiles to link IN to OUT through all nine. Click, or use Tab then Enter.","x":690,"y":16,"width":350,"height":70,"color":"ink"}},{"op":"create","object":{"id":"light_puzzle","kind":"scene","title":"Connect the light","x":24,"y":96,"width":1032,"height":420,"color":"gold","interaction":"Rotate the tiles clockwise to carry light from IN to OUT through all nine tiles.","state":{"turns":[1,0,0,2,0,3,2,0,0],"moves":0},"html":"<style>
*{box-sizing:border-box} .play{height:100%;min-height:420px;background:#f6f3ea;color:#26342f;border-radius:20px;padding:28px;display:grid;grid-template-columns:460px 1fr;gap:28px;font-family:system-ui,sans-serif;font-size:17px} .board-side{display:flex;align-items:center;justify-content:center} .board{position:relative;width:284px} .grid{display:grid;grid-template-columns:repeat(3,88px);gap:10px} .tile{position:relative;width:88px;height:88px;padding:0;border:2px solid #b8c4bd;background:#e2e8e2;border-radius:14px;cursor:pointer;overflow:hidden;color:#26342f} .tile:hover{border-color:#526b5c;background:#d5dfd6} .tile:focus-visible,.action:focus-visible{outline:4px solid #397ca2;outline-offset:3px} .tile.lit{background:#ffedb0;border-color:#b68c24} .tile svg{width:100%;height:100%;display:block} .num{position:absolute;left:7px;top:3px;font-size:16px;font-weight:650;line-height:1} .port{position:absolute;font-size:18px;font-weight:800;white-space:nowrap} .in{left:-67px;top:31px;color:#8a650b} .out{right:-77px;bottom:31px;color:#64736b} .out.on{color:#8a650b} .side{display:flex;flex-direction:column;justify-content:center;align-items:flex-start} .eyebrow{margin:0 0 10px;font-size:16px;letter-spacing:.08em;font-weight:750;color:#64736b} h2{font-size:29px;line-height:1.15;margin:0 0 18px} .count{font-size:48px;font-weight:750;line-height:1;margin:0} .count span{font-size:23px;font-weight:500;color:#64736b} .caption{margin:8px 0 17px;font-size:17px} .status{min-height:48px;margin:0 0 16px;line-height:1.4;max-width:390px} .actions{display:flex;gap:12px;flex-wrap:wrap} .action{padding:11px 17px;border:1px solid #87998d;border-radius:10px;background:#fffdf6;color:#26342f;font:600 17px system-ui;cursor:pointer} .action:hover{background:#e5eddf} .moves{font-size:16px;color:#64736b;margin:14px 0 0}
</style>
<div class="play"><div class="board-side"><div class="board"><span class="port in">IN →</span><div class="grid" id="grid" aria-label="Nine rotating circuit tiles"></div><span class="port out" id="out">→ OUT</span></div></div><div class="side"><p class="eyebrow">A SMALL CIRCUIT CHALLENGE</p><h2 id="heading">Keep the light moving</h2><p class="count" id="count"></p><p class="caption">tiles connected to IN</p><p class="status" id="status" role="status" aria-live="polite"></p><div class="actions"><button class="action" id="reset">Start over</button><button class="action" id="mix">New scramble</button></div><p class="moves" id="moves"></p></div></div>
<script>
const defaults={turns:[1,0,0,2,0,3,2,0,0],moves:0};let s={...defaults,...workshop.state};const elbows=new Set([2,3,5,6]);const names=['north','east','south','west'];const delta=[[-1,0],[0,1],[1,0],[0,-1]];const grid=document.getElementById('grid');const tiles=[];
function ports(i){const base=elbows.has(i)?[0,1]:[0,2];return base.map(d=>(d+s.turns[i])%4)}
function trace(){const p=Array.from({length:9},(_,i)=>ports(i));const lit=new Set();const q=[];if(p[0].includes(3)){lit.add(0);q.push(0)}while(q.length){const i=q.shift();for(const d of p[i]){const r=Math.floor(i/3)+delta[d][0],c=i%3+delta[d][1];if(r<0||r>2||c<0||c>2)continue;const j=r*3+c;if(p[j].includes((d+2)%4)&&!lit.has(j)){lit.add(j);q.push(j)}}}return{p,lit,exit:lit.has(8)&&p[8].includes(1)}}
for(let i=0;i<9;i++){const b=document.createElement('button');b.className='tile';b.type='button';b.addEventListener('click',()=>{s={...s,turns:s.turns.map((v,j)=>j===i?(v+1)%4:v),moves:s.moves+1};render();workshop.save(s)});grid.appendChild(b);tiles.push(b)}
function render(){const{p,lit,exit}=trace();const done=exit&&lit.size===9;const ends=[[50,0],[100,50],[50,100],[0,50]];tiles.forEach((b,i)=>{const color=lit.has(i)?'#ae7e0d':'#607869';const path=p[i].map(d=>'M50 50 L'+ends[d][0]+' '+ends[d][1]).join(' ');b.className='tile'+(lit.has(i)?' lit':'');b.setAttribute('aria-label','Tile '+(i+1)+', '+p[i].map(d=>names[d]).join(' to ')+(lit.has(i)?', lit':'')+'. Rotate clockwise.');b.innerHTML='<svg viewBox="0 0 100 100" aria-hidden="true"><path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="13" stroke-linecap="round"/><circle cx="50" cy="50" r="10" fill="'+color+'"/></svg><span class="num">'+(i+1)+'</span>'});document.getElementById('count').innerHTML=lit.size+' <span>/ 9</span>';document.getElementById('heading').textContent=done?'Circuit complete!':'Keep the light moving';document.getElementById('status').textContent=done?'You connected every tile and reached OUT. Try another scramble?':exit?'OUT is connected. Can you bring all nine tiles into the route?':'Gold marks the route connected to IN. Match neighboring openings to extend it.';document.getElementById('out').className='port out'+(exit?' on':'');document.getElementById('moves').textContent=s.moves+' '+(s.moves===1?'turn':'turns');}
document.getElementById('reset').addEventListener('click',()=>{s={...s,turns:[...defaults.turns],moves:0};render();workshop.save(s)});document.getElementById('mix').addEventListener('click',()=>{const turns=Array.from({length:9},()=>Math.floor(Math.random()*4));turns[0]=0;s={...s,turns,moves:0};render();workshop.save(s)});workshop.onRestore(next=>{s={...defaults,...next};render()});render();
</script>"}}],"actions":[]}
